// 20.22: THE CONTEXT LIBRARY IS GENERATED by tools/ctx-art.js. The block between the
// ctx-library markers in app.js must be exactly what the generator builds, so a drawing
// edited by hand in app.js (and lost on the next --write) fails here, as does a generator
// change nobody wrote back. Also pins the reference style the designer asked for: one
// uniform stroke, no tapering, the catalogue's groups.
const fs = require('fs'), path = require('path');
const S = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
const T = require(path.join(__dirname, '..', 'tools', 'ctx-art.js'));
let fails = [], n = 0;
const ck = (l, c) => { n++; console.log((c ? 'OK:  ' : 'FAIL:') + ' ' + l); if (!c) fails.push(l); };

const built = T.build();
ck('app.js carries the generated library verbatim (run node tools/ctx-art.js --write after editing the generator)',
   S.indexOf(built) >= 0);
ck('there is exactly one generated library block', S.split('// <ctx-library').length === 2 && S.split('// </ctx-library>').length === 2);
ck('the hand-written library is gone (no second CONTEXT_LIBRARY or BED_STYLE_VARIANTS)',
   S.split('const CONTEXT_LIBRARY = [').length === 2 && S.split('const BED_STYLE_VARIANTS = [').length === 2);

// ONE weight: "keep the lineweight all the same, no tapering".
const lw = /const CTX_LW_OBJ = ([\d.]+), CTX_LW_DET = ([\d.]+), CTX_LW_FINE = ([\d.]+);/.exec(S);
ck('the three context weights are one value', !!lw && lw[1] === lw[2] && lw[2] === lw[3]);

// The catalogue's groups, in order, with Keep clear and Basic kept at the end.
const cats = T.CATS.map(c => c.cat);
ck('the palette groups follow the catalogue: ' + cats.join(', '),
   JSON.stringify(cats) === JSON.stringify(['Guestroom', 'Bathroom', 'Toilets', 'Office', 'Glass', 'Doors', 'Chairs', 'Decor', 'Keep clear', 'Basic']));
ck('no group label carries an ampersand (it rides inside an inline onclick)', cats.every(c => c.indexOf('&') < 0 && c.indexOf("'") < 0));

// Every drawing: no literal fills (only the opaque marker), no stray quotes, and open
// strokes that must stay lines are marked, so the block body does not fill a chord.
let bad = [];
T.CATS.forEach(c => c.items.forEach(it => {
    [it.art && it.art(it.w, it.h), it.side && it.side.art(it.side.w, it.side.h)].filter(Boolean).forEach(svg => {
        if (/fill="(?!none)[^"]+"/.test(svg)) bad.push(it.key + ' has a literal fill');
        if (/stroke-width=/.test(svg)) bad.push(it.key + ' sets its own stroke weight');
    });
}));
ck('no drawing sets a fill or its own stroke weight' + (bad.length ? ': ' + bad.slice(0, 4).join('; ') : ''), bad.length === 0);

// The composite blocks from the catalogue exist and are drawn.
const keys = new Set(); T.CATS.forEach(c => c.items.forEach(it => keys.add(it.key)));
['gr-king-set', 'gr-queen-pair', 'gr-desk', 'gr-media', 'gr-wardrobe-wall', 'ba-vanity-mirror', 'of-workstation', 'of-meeting',
 'gl-door', 'gl-double', 'gl-fixed', 'gl-frameless', 'gl-framed', 'gl-slide', 'dr-pocket', 'dr-barn', 'dr-glass', 'ch-bar', 'ch-banquette', 'fx-ada-toilet']
    .forEach(k => ck('catalogue block ' + k + ' is in the library', keys.has(k)));

// Existing items keep their size (saved walls must not change shape).
const size = {};
T.CATS.forEach(c => c.items.forEach(it => { size[it.key] = [it.w, it.h, it.side ? it.side.w : null, it.side ? it.side.h : null]; }));
const want = { 'bed-queen': [60, 24, 80, 36], 'bed-king': [76, 24, 80, 36], 'bed-full': [54, 24, 75, 36], 'door-guest': [36, 84, null, null],
    'tv-55': [48.5, 28, 4, 28], 'nightstand': [24, 25, 18, 25], 'credenza': [72, 30, 20, 30], 'sofa': [84, 32, 36, 32], 'toilet-ada': [15, 18, 28, 18] };
Object.keys(want).forEach(k => ck(k + ' keeps its size and side size', JSON.stringify(size[k]) === JSON.stringify(want[k])));

console.log('--- Summary ---');
if (fails.length) { console.log(fails.length + ' FAILURES'); process.exit(1); }
console.log('ALL PASSED (' + n + ')');
